  timeZone: 'America/Sao_Paulo', dateStyle: 'short', timeStyle: 'medium'
}).format(new Date());

const linhas = [
  '🚨 <b>Erro no workflow</b>',
  'Quando: ' + esc(quando),
  wf.name ? 'Workflow: ' + esc(wf.name) : '',
  node.name ? 'Nó: ' + esc(node.name) : '',
  'Motivo: ' + esc(err.message || 'desconhecido').slice(0, 500),
  exec.id ? 'Execução: #' + esc(exec.id) : '',
  exec.url ? 'Ver: ' + esc(exec.url) : '',
];

return [{ json: { texto: linhas.filter(Boolean).join('\n') } }];
